@using sv_c2a4bd6cd930458e867b69cd2d9c3610.Services
@inject ISettingsService SettingsService

<div class="settings-section">
    <h2>Notifications</h2>

    @if (_loading)
    {
        <p class="loading-message">Loading notification preferences...</p>
    }
    else
    {
        <div class="notifications-form">
            <div class="toggle-group">
                <label class="toggle-label">
                    <input type="checkbox" @bind="_emailNotifications" class="toggle-input" />
                    <span class="toggle-switch"></span>
                    <span>Email Notifications</span>
                </label>
            </div>

            <div class="toggle-group">
                <label class="toggle-label">
                    <input type="checkbox" @bind="_pushNotifications" class="toggle-input" />
                    <span class="toggle-switch"></span>
                    <span>Push Notifications</span>
                </label>
            </div>

            <div class="toggle-group">
                <label class="toggle-label">
                    <input type="checkbox" @bind="_weeklyDigest" class="toggle-input" />
                    <span class="toggle-switch"></span>
                    <span>Weekly Digest</span>
                </label>
            </div>

            <div class="channels-section">
                <h3>Muted Channels</h3>
                @foreach (var channel in _allChannels)
                {
                    <label class="channel-item">
                        <input type="checkbox"
                               checked="@_mutedChannels.Contains(channel)"
                               @onchange="e => ToggleChannel(channel, (bool)e.Value!)" />
                        <span>@channel</span>
                    </label>
                }
            </div>

            <div class="form-actions">
                <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
                    @(_saving ? "Saving..." : "Save Preferences")
                </button>
            </div>

            @if (_successMessage is not null)
            {
                <div class="toast toast-success">@_successMessage</div>
            }
        </div>
    }
</div>

@code {
    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private HashSet<string> _mutedChannels = new();
    private bool _loading = true;
    private bool _saving;
    private string? _successMessage;

    private static readonly string[] _allChannels = ["general", "announcements", "engineering", "design", "marketing", "support"];

    protected override async Task OnInitializedAsync()
    {
        _loading = true;
        var prefs = await SettingsService.GetNotificationPrefsAsync();
        _emailNotifications = prefs.EmailNotifications;
        _pushNotifications = prefs.PushNotifications;
        _weeklyDigest = prefs.WeeklyDigest;
        _mutedChannels = new HashSet<string>(prefs.MutedChannels);
        _loading = false;
    }

    private void ToggleChannel(string channel, bool muted)
    {
        if (muted)
            _mutedChannels.Add(channel);
        else
            _mutedChannels.Remove(channel);
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _successMessage = null;
        var prefs = new NotificationPrefs(_emailNotifications, _pushNotifications, _weeklyDigest, _mutedChannels.ToList());
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        _saving = false;
        _successMessage = "Preferences saved successfully!";
        _ = DismissToastAsync();
    }

    private async Task DismissToastAsync()
    {
        await Task.Delay(3000);
        _successMessage = null;
        await InvokeAsync(StateHasChanged);
    }
}
"}

{"path": "/tmp/sv-c2a4bd6cd930458e867b69cd2d9c3610/Components/Pages/Settings/SecuritySection.razor", "file_text": "@namespace sv_c2a4bd6cd930458e867b69cd2d9c3610.Components.Pages.Settings
@using sv_c2a4bd6cd930458e867b69cd2d9c3610.Services
@inject ISettingsService SettingsService

<div class="settings-section">
    <h2>Security</h2>

    @if (_loading)
    {
        <p class="loading-message">Loading security settings...</p>
    }
    else
    {
        <!-- Change Password Panel -->
        <div class="expandable-panel">
            <button class="panel-header" @onclick="() => _passwordPanelOpen = !_passwordPanelOpen">
                <span>Change Password</span>
                <span class="panel-toggle">@(_passwordPanelOpen ? "▲" : "▼")</span>
            </button>

            @if (_passwordPanelOpen)
            {
                <div class="panel-content">
                    <div class="form-group">
                        <label for="currentPassword">Current Password</label>
                        <input id="currentPassword" type="password" @bind="_currentPassword" class="form-input" />
                    </div>
                    <div class="form-group">
                        <label for="newPassword">New Password</label>
                        <input id="newPassword" type="password" @bind="_newPassword" class="form-input" />
                    </div>
                    <div class="form-group">
                        <label for="confirmPassword">Confirm Password</label>
                        <input id="confirmPassword" type="password" @bind="_confirmPassword" class="form-input" />
                    </div>

                    @if (_passwordError is not null)
                    {
                        <div class="toast toast-error">@_passwordError</div>
                    }
                    @if (_passwordSuccess is not null)
                    {
                        <div class="toast toast-success">@_passwordSuccess</div>
                    }

                    <button class="btn btn-primary" @onclick="ChangePasswordAsync" disabled="@_changingPassword">
                        @(_changingPassword ? "Updating..." : "Update Password")
                    </button>
                </div>
            }
        </div>

        <!-- Two-Factor Authentication -->
        <div class="security-item">
            <div class="twofa-row">
                <span>Two-Factor Authentication</span>
                <span class="status-indicator @(_twoFactorEnabled ? "status-enabled" : "status-disabled")">
                    @(_twoFactorEnabled ? "Enabled" : "Disabled")
                </span>
                <label class="toggle-label">
                    <input type="checkbox" @bind="_twoFactorEnabled" class="toggle-input" />
                    <span class="toggle-switch"></span>
                </label>
            </div>
            @if (_lastPasswordChange.HasValue)
            {
                <p class="security-info">Last password change: @_lastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
            }
        </div>

        <!-- Active Sessions -->
        <div class="sessions-section">
            <h3>Active Sessions</h3>
            <table class="sessions-table">
                <thead>
                    <tr>
                        <th>Device</th>
                        <th>Location</th>
                        <th>Last Active</th>
                        <th>Action</th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var session in _sessions)
                    {
                        <tr>
                            <td>@session.Device</td>
                            <td>@session.Location</td>
                            <td>@session.LastActive.ToString("g")</td>
                            <td>
                                @if (session != _sessions.FirstOrDefault())
                                {
                                    <button class="btn btn-danger btn-sm"
                                            @onclick="() => ConfirmRevoke(session)">
                                        Revoke
                                    </button>
                                }
                                else
                                {
                                    <span class="current-session-badge">Current</span>
                                }
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>

        <!-- Revoke Confirmation Dialog -->
        @if (_sessionToRevoke is not null)
        {
            <div class="modal-overlay" @onclick="CancelRevoke">
                <div class="modal-dialog" @onclick:stopPropagation="true">
                    <h3>Revoke Session</h3>
                    <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke.Device</strong> in <strong>@_sessionToRevoke.Location</strong>?</p>
                    <div class="modal-actions">
                        <button class="btn btn-danger" @onclick="RevokeSessionAsync" disabled="@_revoking">
                            @(_revoking ? "Revoking..." : "Revoke")
                        </button>
                        <button class="btn btn-secondary" @onclick="CancelRevoke" disabled="@_revoking">
                            Cancel
                        </button>
                    </div>
                </div>
            </div>
        }
    }
</div>

@code {
    private bool _loading = true;
    private bool _passwordPanelOpen;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private bool _changingPassword;
    private string? _passwordError;
    private string? _passwordSuccess;
    private bool _twoFactorEnabled;
    private DateTime? _lastPasswordChange;
    private List<ActiveSession> _sessions = new();
    private ActiveSession? _sessionToRevoke;
    private bool _revoking;

    protected override async Task OnInitializedAsync()
    {
        _loading = true;
        var settings = await SettingsService.GetSecuritySettingsAsync();
        _twoFactorEnabled = settings.TwoFactorEnabled;
        _lastPasswordChange = settings.LastPasswordChange;
        _sessions = settings.Sessions;
        _loading = false;
    }

    private async Task ChangePasswordAsync()
    {
        _passwordError = null;
        _passwordSuccess = null;

        if (string.IsNullOrWhiteSpace(_newPassword))
        {
            _passwordError = "New password cannot be empty.";
            return;
        }

        if (_newPassword != _confirmPassword)
        {
            _passwordError = "New password and confirmation do not match.";
            return;
        }

        _changingPassword = true;
        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
        _changingPassword = false;
        _passwordSuccess = "Password updated successfully!";
        _currentPassword = "";
        _newPassword = "";
        _confirmPassword = "";
    }

    private void ConfirmRevoke(ActiveSession session)
    {
        _sessionToRevoke = session;
    }

    private void CancelRevoke()
    {
        _sessionToRevoke = null;
    }

    private async Task RevokeSessionAsync()
    {
        if (_sessionToRevoke is null) return;

        _revoking = true;
        await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
        _sessions.Remove(_sessionToRevoke);
        _sessionToRevoke = null;
        _revoking = false;
    }
}
"}

{"path": "/tmp/sv-c2a4bd6cd930458e867b69cd2d9c3610/Components/Pages/Settings/AppearanceSection.razor", "file_text": "@namespace sv_c2a4bd6cd930458e867b69cd2d9c3610.Components.Pages.Settings
@using sv_c2a4bd6cd930458e867b69cd2d9c3610.Services
@inject ISettingsService SettingsService

<div class="settings-section">
    <h2>Appearance</h2>

    @if (_loading)
    {
        <p class="loading-message">Loading appearance settings...</p>
    }
    else
    {
        <div class="appearance-form">
            <!-- Theme Selector -->
            <div class="form-group">
                <label>Theme</label>
                <div class="radio-group">
                    @foreach (var theme in _themes)
                    {
                        <label class="radio-label">
                            <input type="radio" name="theme" value="@theme"
                                   checked="@(_theme == theme)"
                                   @onchange="() => _theme = theme" />
                            <span>@theme</span>
                        </label>
                    }
                </div>
            </div>

            <!-- Font Size Selector -->
            <div class="form-group">
                <label>Font Size</label>
                <div class="radio-group">
                    @foreach (var size in _fontSizes)
                    {
                        <label class="radio-label">
                            <input type="radio" name="fontSize" value="@size"
                                   checked="@(_fontSize == size)"
                                   @onchange="() => _fontSize = size" />
                            <span>@size</span>
                        </label>
                    }
                </div>
            </div>

            <!-- Language Dropdown -->
            <div class="form-group">
                <label for="language">Language</label>
                <select id="language" @bind="_language" class="form-input">
                    @foreach (var lang in _languages)
                    {
                        <option value="@lang">@lang</option>
                    }
                </select>
            </div>

            <!-- Compact Mode Toggle -->
            <div class="toggle-group">
                <label class="toggle-label">
                    <input type="checkbox" @bind="_compactMode" class="toggle-input" />
                    <span class="toggle-switch"></span>
                    <span>Compact Mode</span>
                </label>
            </div>

            <!-- Live Preview -->
            <div class="preview-area @GetPreviewClasses()">
                <h4>Live Preview</h4>
                <p class="preview-text">This is how your content will look with the selected settings.</p>
                <div class="preview-card">
                    <strong>Sample Card</strong>
                    <p>A demonstration of the current appearance configuration.</p>
                </div>
            </div>

            <div class="form-actions">
                <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
                    @(_saving ? "Saving..." : "Save")
                </button>
            </div>

            @if (_successMessage is not null)
            {
                <div class="toast toast-success">@_successMessage</div>
            }
        </div>
    }
</div>

@code {
    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;
    private bool _loading = true;
    private bool _saving;
    private string? _successMessage;

    private static readonly string[] _themes = ["Light", "Dark", "System"];
    private static readonly string[] _fontSizes = ["Small", "Medium", "Large"];
    private static readonly string[] _languages = ["English", "Spanish", "French", "German", "Japanese", "Chinese"];

    protected override async Task OnInitializedAsync()
    {
        _loading = true;
        var settings = await SettingsService.GetAppearanceAsync();
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

    private string GetPreviewClasses()
    {
        var themeClass = _theme.ToLowerInvariant() switch
        {
            "dark" => "preview-dark",
            "light" => "preview-light",
            _ => "preview-light"
        };
        var sizeClass = _fontSize.ToLowerInvariant() switch
        {
            "small" => "preview-font-small",
            "large" => "preview-font-large",
            _ => "preview-font-medium"
        };
        var compactClass = _compactMode ? "preview-compact" : "";
        return $"{themeClass} {sizeClass} {compactClass}";
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _successMessage = null;
        var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        _saving = false;
        _successMessage = "Appearance saved successfully!";
        _ = DismissToastAsync();
    }

    private async Task DismissToastAsync()
    {
        await Task.Delay(3000);
        _successMessage = null;
        await InvokeAsync(StateHasChanged);
    }
}
"}

